    (C.isPopup?(document.body||document.documentElement):document.documentElement).append(root);
    q('[data-close]').onclick=()=>{if(C.isPopup)window.close();else{root.remove();root=null;}};q('[data-settings]').onclick=()=>{settingsFormReady=false;showSettings=true;render();};q('[data-settings-back]').onclick=()=>{settingsFormReady=false;showSettings=false;render();};q('[data-start-indexing]').onclick=async()=>{forceDashboard=true;manualOpen=null;render();await act('start');};
